      title: '综合建议',
      content: {
        prioritizedFormulas: formulas
          .sort((a, b) => b.confidence - a.confidence)
          .map((f, idx) => ({
            rank: idx + 1,
            formulaName: f.name,
            confidence: f.confidence,
