      setError(err?.response?.data?.detail || err?.message || '创建失败，请重试');
    } finally {
      setLoading(false);
    }
  }, [name, slug, description, plan, onCreate]);

  const handleClose = useCallback(() => {
    setStep('basic');
    setName('');
    setSlug('');
    setDescription('');
    setPlan('free');
    setAutoSlug(true);
    setLogoUrl(null);
    setInviteEmail('');
